   375→/* ===================================================
   376→   QUICK MODE — Web Speech API
   377→   No WebSocket. No backend. Browser-only.
   378→   =================================================== */
   379→
   380→const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
   381→
   382→function getRecognitionLang() {
   383→    return localStorage.getItem('recognitionLang') || navigator.language || 'en-US';
   384→}
   385→
   386→function initRecognition() {
   387→    if (!SpeechRecognition) return;
   388→
   389→    recognition = new SpeechRecognition();
   390→    recognition.continuous      = true;
   391→    recognition.interimResults  = true;
   392→    recognition.lang            = getRecognitionLang();
   393→    recognition.maxAlternatives = 1;
   394→
   395→    recognition.onstart = () => {
   396→        isListening      = true;
   397→        quickFinalTranscript = '';
   398→        showLiveTranscript('', 'quick');
   399→        quickBtn.classList.add('recording');
   400→        quickRing.classList.add('recording');
   401→        quickBtn.setAttribute('aria-pressed', 'true');
   402→        brainstormBtn.disabled = true;
   403→        replayButton.disabled  = true;
   404→        micHint.textContent = 'Listening… tap Quick to stop';
   405→        micHint.classList.add('active');
   406→        micHint.classList.remove('brainstorm-active', 'processing');
   407→    };
   408→
   409→    recognition.onresult = (event) => {
   410→        let interim = '';
   411→        for (let i = event.resultIndex; i < event.results.length; i++) {
   412→            const result = event.results[i];
   413→            if (result.isFinal) {
   414→                quickFinalTranscript += result[0].transcript + ' ';
   415→            } else {
   416→                interim += result[0].transcript;
   417→            }
   418→        }
   419→        const displayText = (quickFinalTranscript + interim).trim();
   420→        updateLiveText(displayText);
   421→        resetSilenceTimer();
   422→    };
   423→
   424→    recognition.onerror = (event) => {
   425→        if (event.error !== 'no-speech') {
   426→            console.warn('Speech recognition error:', event.error);
   427→        }
   428→        stopQuickMode();
   429→    };
   430→
   431→    recognition.onend = () => {
   432→        // If we didn't stop manually, recognition auto-stopped
   433→        if (isListening) {
   434→            finishQuickRecording();
   435→        }
   436→    };
   437→}
   438→
   439→function resetSilenceTimer() {
   440→    clearTimeout(silenceTimer);
   441→    silenceTimer = setTimeout(() => {
   442→        if (isListening) stopQuickMode();
   443→    }, SILENCE_DELAY);
   444→}
   445→
   446→function startQuickMode() {
   447→    if (isListening || isBrainstormRecording || isBrainstormProcessing || isReplaying) return;
   448→    if (!recognition) {
   449→        alert('Speech recognition is not available in this browser.');
   450→        return;
   451→    }
   452→    hideTranscriptBar();
   453→    // Stop wake word listener if running (can't run both concurrently)
   454→    if (wakeWordListening) stopWakeWordListening();
   455→    try {
   456→        recognition.start();
   457→    } catch (e) {
   458→        console.warn('Could not start recognition:', e);
   459→        initRecognition();
   460→        try { recognition.start(); } catch (_) {}
   461→    }
   462→    resetSilenceTimer();
   463→}
   464→
   465→function stopQuickMode() {
   466→    clearTimeout(silenceTimer);
   467→    // Mark as not listening BEFORE calling recognition.stop() so that
   468→    // recognition.onend doesn't also call finishQuickRecording()
   469→    isListening = false;
   470→    if (recognition) {
   471→        try { recognition.stop(); } catch (_) {}
   472→    }
   473→    finishQuickRecording();
   474→}
   475→
   476→function finishQuickRecording() {
   477→    isListening = false;
   478→    clearTimeout(silenceTimer);
   479→    quickBtn.classList.remove('recording');
   480→    quickRing.classList.remove('recording');
   481→    quickBtn.setAttribute('aria-pressed', 'false');
   482→    brainstormBtn.disabled = false;
   483→    micHint.textContent    = '';
   484→    micHint.classList.remove('active');
   485→    hideLiveTranscript();
   486→    updateReplayButtonState();
   487→
   488→    const text = quickFinalTranscript.trim();
   489→    quickFinalTranscript = '';
   490→    if (text) {
   491→        showTranscriptBar(text, 'quick');
   492→    }
   493→
   494→    // Resume hands-free wake word listening
   495→    if (handsFreeEnabled) {
   496→        setTimeout(startWakeWordListening, 400);
   497→    }
   498→}
   499→
   500→quickBtn.addEventListener('click', () => {
   501→    haptic(50);
   502→    if (isListening) {
   503→        stopQuickMode();
   504→    } else if (!isBrainstormRecording && !isBrainstormProcessing && !isReplaying) {
   505→        startQuickMode();
   506→    }
   507→});
