   509→/* ===================================================
   510→   WAKE WORD DETECTION — always-on "Hey Chill" listener
   511→   =================================================== */
   512→
   513→function matchesWakeWord(text) {
   514→    const t = text.toLowerCase().trim();
   515→    // Fuzzy patterns: "hey chill", "hey chil", "a chill", "hay chill", etc.
   516→    return /\b(hey|hay|a)\s+chil{1,2}\b/.test(t);
   517→}
   518→
   519→function initWakeRecognition() {
   520→    if (!SpeechRecognition) return;
   521→
   522→    wakeRecognition = new SpeechRecognition();
   523→    wakeRecognition.continuous      = true;
   524→    wakeRecognition.interimResults  = true;
   525→    wakeRecognition.lang            = getRecognitionLang();
   526→    wakeRecognition.maxAlternatives = 3;
   527→
   528→    wakeRecognition.onresult = (event) => {
   529→        for (let i = event.resultIndex; i < event.results.length; i++) {
   530→            const result = event.results[i];
   531→            for (let j = 0; j < result.length; j++) {
   532→                if (matchesWakeWord(result[j].transcript)) {
   533→                    handleWakeWordDetected();
   534→                    return;
   535→                }
   536→            }
   537→        }
   538→    };
   539→
   540→    wakeRecognition.onerror = (event) => {
   541→        if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
   542→            console.warn('Wake word mic denied:', event.error);
   543→            wakeWordListening = false;
   544→            updateWakeDot();
   545→            return;
   546→        }
   547→        // Transient error — will be restarted by onend handler
   548→    };
   549→
   550→    wakeRecognition.onend = () => {
   551→        wakeWordListening = false;
   552→        updateWakeDot();
   553→        // Auto-restart when not in an active mode
   554→        if (handsFreeEnabled && !isListening && !isBrainstormRecording && !isBrainstormProcessing) {
   555→            setTimeout(startWakeWordListening, 300);
   556→        }
   557→    };
   558→}
   559→
   560→function startWakeWordListening() {
   561→    if (!SpeechRecognition || !handsFreeEnabled) return;
   562→    if (isListening || isBrainstormRecording || isBrainstormProcessing) return;
   563→    if (wakeWordListening) return;
   564→
   565→    if (!wakeRecognition) initWakeRecognition();
   566→
   567→    try {
   568→        wakeRecognition.start();
   569→        wakeWordListening = true;
   570→        updateWakeDot();
   571→    } catch (e) {
   572→        console.warn('Could not start wake recognition:', e);
   573→        wakeWordListening = false;
   574→        // Re-init and try once more next cycle
   575→        initWakeRecognition();
   576→    }
   577→}
   578→
   579→function stopWakeWordListening() {
   580→    wakeWordListening = false;
   581→    updateWakeDot();
   582→    if (wakeRecognition) {
   583→        try { wakeRecognition.stop(); } catch (_) {}
   584→    }
   585→}
   586→
   587→function handleWakeWordDetected() {
   588→    stopWakeWordListening();
   589→    if (!isListening && !isBrainstormRecording && !isBrainstormProcessing && !isReplaying) {
   590→        haptic(50);
   591→        startQuickMode();
   592→    }
   593→}
   594→
   595→function updateWakeDot() {
   596→    if (!wakeDot) return;
   597→    wakeDot.hidden = !(handsFreeEnabled && wakeWordListening);
   598→}
   599→
   600→function setHandsFree(enabled) {
   601→    handsFreeEnabled = enabled;
   602→    localStorage.setItem('handsFreeEnabled', enabled ? '1' : '0');
   603→    if (enabled) {
   604→        startWakeWordListening();
   605→    } else {
   606→        stopWakeWordListening();
   607→    }
   608→    updateWakeDot();
   609→}
