   611→/* ===================================================
   612→   BRAINSTORM MODE — WebSocket + PCM16 audio streaming
   613→   =================================================== */
   614→
   615→function getWebSocketUrl() {
   616→    const backendUrl = localStorage.getItem('brainwaveBackendUrl') || '';
   617→    if (backendUrl) {
   618→        try {
   619→            const url    = new URL(backendUrl);
   620→            const wsProto = url.protocol === 'https:' ? 'wss:' : 'ws:';
   621→            return `${wsProto}//${url.host}/api/v1/ws`;
   622→        } catch (_) { /* fall through to default */ }
   623→    }
   624→    const proto = window.location.protocol === 'https:' ? 'wss' : 'ws';
   625→    return `${proto}://${window.location.host}/api/v1/ws`;
   626→}
   627→
   628→function updateConnectionStatus(status) {
   629→    connectionStatus.className = 'ws-dot';
   630→    switch (status) {
   631→        case 'connected':
   632→            connectionStatus.classList.add('connected');
   633→            connectionStatus.title = 'Connected';
