   648→function initializeWebSocket() {
   649→    ws = new WebSocket(getWebSocketUrl());
   650→
   651→    ws.onopen = () => {
   652→        wsConnected = true;
   653→        updateConnectionStatus('idle');
   654→        if (autoStart && !isBrainstormRecording && !isAutoStarted) {
   655→            isAutoStarted = true;
   656→            startBrainstormRecording();
   657→        }
   658→    };
   659→
   660→    ws.onerror = (error) => {
   661→        console.error('WebSocket error:', error);
   662→        updateConnectionStatus('disconnected');
   663→    };
   664→
   665→    ws.onmessage = (event) => {
   666→        const data = JSON.parse(event.data);
   667→        switch (data.type) {
   668→            case 'status':
   669→                updateConnectionStatus(data.status);
   670→                if (data.status === 'idle') {
   671→                    stopTimer();
   672→                    if (_awaitingBrainstormResult) {
   673→                        _awaitingBrainstormResult = false;
   674→                        isBrainstormProcessing    = false;
   675→                        quickBtn.disabled         = false;
   676→                        brainstormBtn.disabled    = false;
   677→                        micHint.textContent       = '';
   678→                        micHint.classList.remove('active', 'brainstorm-active', 'processing');
   679→                        hideLiveTranscript();
   680→                        updateReplayButtonState();
   681→                        const finalText = brainstormTranscript.trim();
   682→                        brainstormTranscript = '';
   683→                        if (finalText) {
   684→                            showTranscriptBar(finalText, 'brainstorm');
   685→                        }
   686→                        // Resume hands-free after brainstorm completes
   687→                        if (handsFreeEnabled) {
   688→                            setTimeout(startWakeWordListening, 400);
   689→                        }
   690→                    }
   691→                }
   692→                break;
   693→
   694→            case 'text':
   695→                if (data.isNewResponse) {
   696→                    brainstormTranscript = data.content;
   697→                } else {
   698→                    brainstormTranscript += data.content;
   699→                }
   700→                if (isBrainstormProcessing) {
   701→                    updateLiveText(brainstormTranscript);
   702→                }
   703→                break;
   704→
   705→            case 'error':
   706→                alert(data.content);
   707→                updateConnectionStatus('idle');
   708→                _awaitingBrainstormResult = false;
   709→                isBrainstormProcessing    = false;
   710→                quickBtn.disabled         = false;
   711→                brainstormBtn.disabled    = false;
   712→                micHint.textContent       = '';
   713→                micHint.classList.remove('active', 'brainstorm-active', 'processing');
   714→                hideLiveTranscript();
   715→                brainstormTranscript = '';
   716→                updateReplayButtonState();
   717→                if (handsFreeEnabled) {
   718→                    setTimeout(startWakeWordListening, 400);
   719→                }
   720→                break;
   721→        }
   722→    };
   723→
   724→    ws.onclose = () => {
   725→        wsConnected            = false;
   726→        isBrainstormRecording  = false;
   727→        isStopping             = false;
