   737→/* ===== Audio processing ===== */
   738→function createAudioProcessor() {
   739→    processor = audioContext.createScriptProcessor(4096, 1, 1);
   740→    processor.onaudioprocess = async (e) => {
   741→        if (!isBrainstormRecording && !isStopping) return;
   742→
   743→        const inputData = e.inputBuffer.getChannelData(0);
   744→        const pcmData   = new Int16Array(inputData.length);
   745→        for (let i = 0; i < inputData.length; i++) {
   746→            pcmData[i] = Math.max(-32768, Math.min(32767, Math.floor(inputData[i] * 32767)));
   747→        }
   748→
   749→        const combined = new Int16Array(audioBuffer.length + pcmData.length);
   750→        combined.set(audioBuffer);
   751→        combined.set(pcmData, audioBuffer.length);
   752→        audioBuffer = combined;
   753→
   754→        if (audioBuffer.length >= 24000) {
   755→            const sendBuffer = audioBuffer.slice(0, 24000);
   756→            audioBuffer      = audioBuffer.slice(24000);
   757→
   758→            if (ws.readyState === WebSocket.OPEN) {
   759→                ws.send(sendBuffer.buffer);
   760→
   761→                if (storageAvailable && currentSessionId && sessionStartTime) {
   762→                    const deltaMs = performance.now() - sessionStartTime;
   763→                    await appendChunk(currentSessionId, {
   764→                        seq: chunkSeq++, deltaMs,
   765→                        kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
   766→                    });
   767→                }
   768→            }
   769→        }
   770→    };
   771→    return processor;
   772→}
   773→
   774→async function initAudio(audioStream) {
   775→    if (audioContext && audioContext.state !== 'closed') {
   776→        try { await audioContext.close(); } catch (_) {}
   777→    }
   778→    audioContext = new (window.AudioContext || window.webkitAudioContext)();
   779→    source       = audioContext.createMediaStreamSource(audioStream);
   780→    processor    = createAudioProcessor();
   781→    source.connect(processor);
   782→    processor.connect(audioContext.destination);
   783→    if (audioContext.state === 'suspended') await audioContext.resume();
   784→}
