   786→function cleanupAudioResources() {
   787→    if (stream) {
   788→        stream.getTracks().forEach(t => t.stop());
   789→        stream = null;
   790→    }
   791→    if (audioContext && audioContext.state !== 'closed') {
   792→        audioContext.close().catch(() => {});
   793→        audioContext = null;
   794→    }
   795→    source            = null;
   796→    processor         = null;
   797→    streamInitialized = false;
   798→}
