   800→async function startBrainstormRecording() {
   801→    if (isBrainstormRecording || isListening || isBrainstormProcessing || isReplaying) return;
   802→
   803→    if (!ws || ws.readyState !== WebSocket.OPEN) {
   804→        alert('WebSocket is not connected. Please wait or check the backend URL in Settings.');
   805→        return;
   806→    }
   807→
   808→    // Pause wake word listening while brainstorm is active
   809→    if (wakeWordListening) stopWakeWordListening();
   810→
   811→    try {
   812→        brainstormTranscript = '';
   813→        hideTranscriptBar();
   814→
   815→        // Re-use existing stream if still alive, else reinit
   816→        let streamActive = false;
   817→        try {
   818→            streamActive = streamInitialized && stream && stream.active &&
   819→                           stream.getTracks().every(t => t.readyState === 'live');
   820→        } catch (_) { streamActive = false; }
   821→
   822→        if (!streamActive) {
   823→            cleanupAudioResources();
   824→            stream = await navigator.mediaDevices.getUserMedia({
   825→                audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
   826→            });
   827→            streamInitialized = true;
   828→        }
   829→
   830→        if (!audioContext || audioContext.state === 'closed') {
   831→            await initAudio(stream);
   832→        } else if (audioContext.state === 'suspended') {
   833→            await audioContext.resume();
   834→        }
   835→
   836→        isBrainstormRecording = true;
   837→        if (storageAvailable) await createSession();
   838→
   839→        const selectedModel = modelSelect ? modelSelect.value : 'gpt-realtime-mini-2025-12-15';
   840→        ws.send(JSON.stringify({ type: 'start_recording', model: selectedModel }));
   841→
   842→        startTimer();
   843→        brainstormBtn.classList.add('recording');
   844→        brainstormRing.classList.add('recording');
   845→        brainstormBtn.setAttribute('aria-pressed', 'true');
   846→        quickBtn.disabled    = true;
   847→        replayButton.disabled = true;
   848→        micHint.textContent  = 'Recording… tap Brainstorm to stop';
   849→        micHint.classList.add('active', 'brainstorm-active');
   850→        micHint.classList.remove('processing');
   851→        showLiveTranscript('', 'brainstorm');
   852→
   853→    } catch (error) {
   854→        console.error('Error starting Brainstorm:', error);
   855→        isBrainstormRecording = false;
   856→        alert('Error accessing microphone: ' + error.message);
   857→    }
