   860→async function stopBrainstormRecording() {
   861→    if (!isBrainstormRecording) return;
   862→
   863→    isStopping            = true;
   864→    isBrainstormRecording = false;
   865→    const durationMs      = sessionStartTime ? performance.now() - sessionStartTime : 0;
   866→
   867→    stopTimer();
   868→    brainstormBtn.classList.remove('recording');
   869→    brainstormRing.classList.remove('recording');
   870→    brainstormBtn.setAttribute('aria-pressed', 'false');
   871→    brainstormBtn.disabled = true; // keep disabled until WS idle
   872→
   873→    micHint.textContent = 'Processing…';
   874→    micHint.classList.remove('brainstorm-active');
   875→    micHint.classList.add('processing');
   876→
   877→    // Allow any in-flight onaudioprocess callbacks to complete
   878→    await new Promise(resolve => setTimeout(resolve, 100));
   879→
   880→    // Flush remaining audio buffer
   881→    if (audioBuffer.length > 0 && ws.readyState === WebSocket.OPEN) {
   882→        const sendBuffer = audioBuffer.slice();
   883→        ws.send(sendBuffer.buffer);
   884→        if (storageAvailable && currentSessionId && sessionStartTime) {
   885→            const deltaMs = performance.now() - sessionStartTime;
   886→            await appendChunk(currentSessionId, {
   887→                seq: chunkSeq++, deltaMs,
   888→                kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
   889→            });
   890→        }
   891→        audioBuffer = new Int16Array(0);
   892→    }
   893→
   894→    isStopping = false;
   895→
   896→    // Small delay to ensure all audio sent before stop signal
   897→    await new Promise(resolve => setTimeout(resolve, 500));
   898→    ws.send(JSON.stringify({ type: 'stop_recording' }));
   899→
   900→    if (storageAvailable && currentSessionId) {
   901→        await completeSession(currentSessionId, durationMs);
   902→        currentSessionId  = null;
   903→        sessionStartTime  = null;
   904→        chunkSeq          = 0;
   905→    }
   906→
   907→    // Switch to processing state — WS idle handler will finish the flow
   908→    isBrainstormProcessing    = true;
   909→    _awaitingBrainstormResult = true;
   910→    liveText.textContent      = 'Processing…';
   911→    liveText.classList.remove('has-text');
   912→}
