   935→
   936→    isReplaying              = true;
   937→    quickBtn.disabled        = true;
   938→    brainstormBtn.disabled   = true;
   939→    replayButton.disabled    = true;
   940→    replayButton.classList.add('replaying');
   941→    brainstormTranscript     = '';
   942→
   943→    try {
   944→        hideTranscriptBar();
   945→        const chunks = await getSessionChunks(session.id);
   946→        if (chunks.length === 0) throw new Error('No audio chunks found for session');
   947→
   948→        // Wait for WS if needed
   949→        if (!wsConnected || ws.readyState !== WebSocket.OPEN) {
   950→            await new Promise(resolve => {
   951→                const check = setInterval(() => {
   952→                    if (wsConnected && ws.readyState === WebSocket.OPEN) { clearInterval(check); resolve(); }
   953→                }, 100);
