   956→
   957→        const selectedModel = modelSelect ? modelSelect.value : 'gpt-realtime-mini-2025-12-15';
   958→        ws.send(JSON.stringify({ type: 'start_recording', model: selectedModel }));
   959→        await new Promise(resolve => setTimeout(resolve, 200));
   960→
   961→        for (const chunk of chunks.filter(c => c.kind === 'audio' && c.payload)) {
   962→            if (ws.readyState === WebSocket.OPEN) {
   963→                ws.send(chunk.payload);
   964→            } else {
