   969→        ws.send(JSON.stringify({ type: 'stop_recording' }));
   970→
   971→        isBrainstormProcessing    = true;
   972→        _awaitingBrainstormResult = true;
   973→        micHint.textContent       = 'Processing replay…';
   974→        micHint.classList.add('active', 'processing');
   975→        micHint.classList.remove('brainstorm-active');
