  1023→/* ===================================================
  1024→   INDEXEDDB — stores PCM16 chunks for replay
  1025→   =================================================== */
  1026→
  1027→function createDBStores(event) {
  1028→    const d = event.target.result;
  1029→    if (!d.objectStoreNames.contains('sessions')) {
  1030→        const s = d.createObjectStore('sessions', { keyPath: 'id', autoIncrement: true });
  1031→        s.createIndex('status',    'status',    { unique: false });
  1032→        s.createIndex('createdAt', 'createdAt', { unique: false });
  1033→    }
  1034→    if (!d.objectStoreNames.contains('chunks')) {
  1035→        const c = d.createObjectStore('chunks', { keyPath: 'id', autoIncrement: true });
  1036→        c.createIndex('sessionId', 'sessionId', { unique: false });
  1037→        c.createIndex('seq',       'seq',       { unique: false });
  1038→    }
  1039→}
  1040→
  1041→async function initIndexedDB() {
  1042→    return new Promise((resolve) => {
  1043→        const request = indexedDB.open('brainwave-replay', 1);
  1044→
  1045→        request.onerror = () => {
  1046→            console.warn('IndexedDB not available, replay disabled');
  1047→            storageAvailable = false;
  1048→            resolve(false);
  1049→        };
  1050→
  1051→        request.onsuccess = () => {
  1052→            db = request.result;
  1053→            if (!db.objectStoreNames.contains('sessions') || !db.objectStoreNames.contains('chunks')) {
  1054→                db.close();
  1055→                const del = indexedDB.deleteDatabase('brainwave-replay');
  1056→                del.onsuccess = () => {
  1057→                    const reopen = indexedDB.open('brainwave-replay', 1);
  1058→                    reopen.onsuccess       = () => { db = reopen.result; storageAvailable = true; updateReplayButtonState(); resolve(true); };
  1059→                    reopen.onerror         = () => { storageAvailable = false; resolve(false); };
  1060→                    reopen.onupgradeneeded = createDBStores;
  1061→                };
  1062→                del.onerror = () => { storageAvailable = false; resolve(false); };
  1063→                return;
  1064→            }
  1065→            storageAvailable = true;
  1066→            updateReplayButtonState();
  1067→            resolve(true);
  1068→        };
  1069→
  1070→        request.onupgradeneeded = createDBStores;
  1071→    });
  1072→}
  1073→
  1074→async function createSession() {
  1075→    if (!db) return null;
  1076→    return new Promise((resolve, reject) => {
  1077→        const tx    = db.transaction(['sessions'], 'readwrite');
  1078→        const store = tx.objectStore('sessions');
  1079→        const req   = store.add({ createdAt: new Date(), status: 'recording', sampleRate: 24000, channelCount: 1, durationMs: 0 });
  1080→        req.onsuccess = () => {
  1081→            currentSessionId  = req.result;
  1082→            sessionStartTime  = performance.now();
  1083→            chunkSeq          = 0;
  1084→            appendChunk(currentSessionId, { seq: 0, deltaMs: 0, kind: 'start', payload: null, byteLength: 0 });
  1085→            resolve(currentSessionId);
  1086→        };
  1087→        req.onerror = () => reject(req.error);
  1088→    });
  1089→}
  1090→
  1091→async function appendChunk(sessionId, chunk) {
  1092→    if (!db || !sessionId) return;
  1093→    return new Promise((resolve) => {
  1094→        const tx    = db.transaction(['chunks'], 'readwrite');
  1095→        const store = tx.objectStore('chunks');
  1096→        const req   = store.add({ sessionId, seq: chunk.seq, deltaMs: chunk.deltaMs, kind: chunk.kind, payload: chunk.payload, byteLength: chunk.byteLength });
  1097→        req.onsuccess = () => resolve();
  1098→        req.onerror   = () => resolve(); // don't fail recording on storage error
  1099→    });
  1100→}
  1101→
  1102→async function completeSession(sessionId, durationMs) {
  1103→    if (!db || !sessionId) return;
  1104→    return new Promise((resolve) => {
  1105→        const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1106→        const sessionsStore = tx.objectStore('sessions');
  1107→        const chunksStore   = tx.objectStore('chunks');
  1108→        const req           = sessionsStore.get(sessionId);
  1109→        req.onsuccess = () => {
  1110→            const sess = req.result;
  1111→            sess.status    = 'completed';
  1112→            sess.durationMs = durationMs;
  1113→            sessionsStore.put(sess);
  1114→            chunksStore.add({ sessionId, seq: chunkSeq++, deltaMs: durationMs, kind: 'stop', payload: null, byteLength: 0 });
  1115→            enforceQuota({ maxSessions: 5 });
  1116→            resolve();
  1117→        };
  1118→        req.onerror = () => resolve();
  1119→    });
  1120→}
  1121→
  1122→async function enforceQuota({ maxSessions }) {
  1123→    if (!db) return;
  1124→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1125→    const sessionsStore = tx.objectStore('sessions');
  1126→    const sessions      = [];
  1127→    sessionsStore.index('createdAt').openCursor().onsuccess = (event) => {
  1128→        const cursor = event.target.result;
  1129→        if (cursor) { sessions.push(cursor.value); cursor.continue(); }
  1130→        else {
  1131→            sessions.sort((a, b) => a.createdAt - b.createdAt);
  1132→            while (sessions.length > maxSessions) deleteSession(sessions.shift().id);
  1133→        }
  1134→    };
  1135→}
  1136→
  1137→async function deleteSession(sessionId) {
  1138→    if (!db) return;
  1139→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1140→    const sessionsStore = tx.objectStore('sessions');
  1141→    const chunksStore   = tx.objectStore('chunks');
  1142→    chunksStore.index('sessionId').openKeyCursor(IDBKeyRange.only(sessionId)).onsuccess = (event) => {
  1143→        const cursor = event.target.result;
  1144→        if (cursor) { chunksStore.delete(cursor.primaryKey); cursor.continue(); }
  1145→    };
  1146→    sessionsStore.delete(sessionId);
  1147→}
  1148→
  1149→async function getLatestCompletedSession() {
  1150→    if (!db) return null;
  1151→    return new Promise((resolve) => {
  1152→        const tx    = db.transaction(['sessions'], 'readonly');
  1153→        const req   = tx.objectStore('sessions').index('status').getAll('completed');
  1154→        req.onsuccess = () => {
  1155→            const sessions = req.result;
  1156→            if (!sessions.length) { resolve(null); return; }
  1157→            sessions.sort((a, b) => b.createdAt - a.createdAt);
  1158→            resolve(sessions[0]);
  1159→        };
  1160→        req.onerror = () => resolve(null);
  1161→    });
  1162→}
  1163→
  1164→async function getSessionChunks(sessionId) {
  1165→    if (!db || !sessionId) return [];
  1166→    return new Promise((resolve) => {
  1167→        const tx  = db.transaction(['chunks'], 'readonly');
  1168→        const req = tx.objectStore('chunks').index('sessionId').getAll(sessionId);
  1169→        req.onsuccess = () => {
  1170→            const chunks = req.result;
  1171→            chunks.sort((a, b) => a.seq - b.seq);
  1172→            resolve(chunks);
  1173→        };
  1174→        req.onerror = () => resolve([]);
  1175→    });
  1176→}
