    backendUrlInput.value = localStorage.getItem('brainwaveBackendUrl') || '';
    langSelect.value      = localStorage.getItem('recognitionLang') || '';
    if (handsFreeToggle) handsFreeToggle.checked = handsFreeEnabled;
